import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val s = scanner.next()
    val n = scanner.nextInt()
    val len = s.length

    val min = if (n > len) (len + n) / 2 else n
    val max = (len + n) / 2

    var temp = 0
    for (i in 0 until len) {
        for (j in 1..(len - i) / 2) {
            var key = true
            for (k in 1..j) {
                if (s[i + k - 1] != s[i + k + j - 1]) {
                    key = false
                    break
                }
            }
            if (key && j > temp) temp = j
        }
    }

    fun check(a: Int): Boolean {
        for (i in 1..a - n) {
            if (s[len - i] != s[len - i - a]) return false
        }
        return true
    }

    var ans = 0
    for (i in max downTo min) {
        if (check(i)) {
            ans = i
            break
        }
    }
    if (min > ans) ans = min
    if (temp > ans) ans = temp
    println(2 * ans)
}

